package com.bank.flink.bp;

// A finite buffer pool for one channel. Credits = free slots a sender may use.
class BufferPool {
    private final int capacity;
    private int used = 0;

    BufferPool(int capacity) {
        this.capacity = capacity;
    }

    // Credits the receiver can advertise upstream.
    int availableCredits() {
        return capacity - used;
    }

    // Sender writes one record if a credit is free; returns success.
    boolean offer() {
        if (used < capacity) { used++; return true; }
        return false; // no credit -> backpressure
    }

    // Receiver consumes one record, freeing a credit.
    boolean poll() {
        if (used > 0) { used--; return true; }
        return false;
    }

    boolean isFull() { return used >= capacity; }
    int getUsed() { return used; }
}
