package com.bank.flink.bp;

import java.util.logging.Logger;

// An operator that consumes from its input buffer at a fixed rate and
// produces into the downstream buffer only if downstream has credits.
class Operator {
    private static final Logger log = Logger.getLogger(Operator.class.getName());

    private final String name;
    private final int ratePerTick;     // how many records it can process per tick
    private final BufferPool input;    // this operator's input buffer
    private final BufferPool output;   // downstream operator's input buffer (null for sink)
    private long processed = 0;
    private boolean backpressured = false;

    Operator(String name, int ratePerTick, BufferPool input, BufferPool output) {
        this.name = name;
        this.ratePerTick = ratePerTick;
        this.input = input;
        this.output = output;
    }

    void tick() {
        backpressured = false;
        for (int i = 0; i < ratePerTick; i++) {
            if (!input.poll()) break; // nothing to consume
            if (output != null && !output.offer()) {
                // downstream has no credits -> we are backpressured; put record back
                input.offer();
                backpressured = true;
                log.warning(() -> name + " BACKPRESSURED (downstream buffer full)");
                break;
            }
            processed++;
        }
    }

    boolean isBackpressured() { return backpressured; }
    long getProcessed() { return processed; }
    String getName() { return name; }
}
