package com.bank.flink.bp;

import java.util.logging.Logger;

// Wires source -> enrich -> slow sink and runs ticks, propagating backpressure.
class BackpressureChain {
    private static final Logger log = Logger.getLogger(BackpressureChain.class.getName());

    private final BufferPool enrichInput;   // between source and enrich
    private final BufferPool sinkInput;      // between enrich and sink
    private final Operator source;
    private final Operator enrich;
    private final Operator sink;
    private long sourceIntake = 0;

    BackpressureChain(int bufferCap, int sourceRate, int sinkRate) {
        this.enrichInput = new BufferPool(bufferCap);
        this.sinkInput = new BufferPool(bufferCap);
        // Source produces into enrichInput; it reads from an "infinite" Kafka (simulated).
        this.source = new Operator("Source", sourceRate, new BufferPool(Integer.MAX_VALUE), enrichInput);
        this.enrich = new Operator("Enrich", sourceRate, enrichInput, sinkInput);
        this.sink = new Operator("Sink", sinkRate, sinkInput, null); // slow, no downstream
    }

    void runTicks(int ticks) {
        for (int t = 1; t <= ticks; t++) {
            final int tick = t;
            // Source tries to intake fresh records from Kafka into its own input first.
            int before = source.getInputUsedForDemo();
            source.feedFromKafka(5); // simulate 5 fresh records available each tick
            sink.tick();     // slow sink drains sinkInput
            enrich.tick();   // enrich moves enrichInput -> sinkInput (may backpressure)
            source.tick();   // source moves its input -> enrichInput (may backpressure)
            long intakeThisTick = source.getProcessed() - sourceIntake;
            sourceIntake = source.getProcessed();
            log.info(() -> "tick " + tick + " | source intake=" + intakeThisTick
                    + " enrichBuf=" + enrichInput.getUsed() + " sinkBuf=" + sinkInput.getUsed()
                    + " | sourceBP=" + source.isBackpressured()
                    + " enrichBP=" + enrich.isBackpressured());
        }
    }

    Operator getSource() { return source; }
    Operator getSink() { return sink; }
}
