package com.bank.flink.bp;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: fast source, slow sink. Backpressure throttles the source
// to the sink's speed with NO data loss.
public class BackpressureDemo {
    private static final Logger log = Logger.getLogger(BackpressureDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BpLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // buffers of 4, source wants 5/tick, sink only does 1/tick.
        BackpressureChain chain = new BackpressureChain(4, 5, 1);
        chain.runTicks(5);
        log.info(() -> "Sink processed total = " + chain.getSink().getProcessed()
                + " (source throttled to match; nothing lost, Kafka lag absorbs the rest)");
    }
}

// ─── Would be in BpLogFormatter.java in a real project ───
class BpLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
